ALTER TABLE public.works ADD COLUMN is_pilot boolean NOT NULL DEFAULT false;
CREATE TABLE public.financial_groups(id uuid PRIMARY KEY, work_id uuid REFERENCES public.works(id), source text NOT NULL DEFAULT 'manual' CHECK(source IN ('manual','contract','purchase')), total numeric NOT NULL CHECK(total>0), created_by uuid DEFAULT auth.uid(), created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT ON public.financial_groups TO authenticated; GRANT ALL ON public.financial_groups TO service_role;
ALTER TABLE public.financial_groups ENABLE ROW LEVEL SECURITY;
CREATE POLICY groups_access ON public.financial_groups FOR ALL TO authenticated USING(public.can_see_costs(auth.uid())) WITH CHECK(public.can_see_costs(auth.uid()));
CREATE UNIQUE INDEX contract_receipts_once ON public.financial_groups(work_id) WHERE source='contract';
ALTER TABLE public.financial_entries ADD COLUMN group_id uuid REFERENCES public.financial_groups(id), ADD COLUMN installment_index integer NOT NULL DEFAULT 1 CHECK(installment_index>0), ADD COLUMN installment_count integer NOT NULL DEFAULT 1 CHECK(installment_count>=installment_index), ADD COLUMN payment_method text, ADD COLUMN notes text, ADD COLUMN cost_center text, ADD COLUMN file_path text, ADD COLUMN payable_order_id uuid REFERENCES public.purchase_orders(id);
CREATE UNIQUE INDEX installment_once ON public.financial_entries(group_id,installment_index) WHERE group_id IS NOT NULL;
COMMENT ON COLUMN public.financial_entries.purchase_order_id IS 'DEPRECATED for new installment purchases: use payable_order_id; legacy single-payment orders remain readable.';
ALTER TABLE public.financial_settlements ADD COLUMN payment_method text, ADD COLUMN notes text;
CREATE OR REPLACE FUNCTION public.guard_installment_entry() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE o public.purchase_orders; g public.financial_groups; allocated numeric; BEGIN
IF new.payable_order_id IS NOT NULL THEN SELECT * INTO o FROM public.purchase_orders WHERE id=new.payable_order_id; IF NOT FOUND OR new.direction<>'saida' OR new.work_id IS DISTINCT FROM o.work_id OR new.purchase_order_id IS NOT NULL THEN RAISE EXCEPTION 'Parcela de compra inválida.'; END IF; END IF;
IF new.group_id IS NOT NULL THEN SELECT * INTO g FROM public.financial_groups WHERE id=new.group_id FOR UPDATE; IF NOT FOUND OR new.work_id IS DISTINCT FROM g.work_id THEN RAISE EXCEPTION 'Grupo de parcelas inválido.'; END IF; SELECT coalesce(sum(amount),0) INTO allocated FROM public.financial_entries WHERE group_id=g.id AND id<>new.id; IF allocated+new.amount>g.total THEN RAISE EXCEPTION 'Parcelas excedem o valor total.'; END IF; END IF;
IF TG_OP='UPDATE' AND (old.group_id IS NOT NULL OR old.payable_order_id IS NOT NULL) AND (to_jsonb(new)-ARRAY['incurred','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['incurred','updated_at','updated_by']) THEN RAISE EXCEPTION 'Parcelas preservadas; baixas são registradas separadamente.'; END IF; RETURN new; END $$;
CREATE TRIGGER installment_entry_guard BEFORE INSERT OR UPDATE ON public.financial_entries FOR EACH ROW EXECUTE FUNCTION public.guard_installment_entry();
CREATE OR REPLACE FUNCTION public.create_financial_installments(_request_id uuid,_work_id uuid,_source text,_description text,_direction text,_category text,_person_id uuid,_total numeric,_rows jsonb,_incurred boolean,_payment_method text,_notes text,_cost_center text,_file_path text) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE row jsonb; n integer; idx integer:=0; total_rows numeric; existing uuid; BEGIN
IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão.'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(_request_id::text,0)); SELECT id INTO existing FROM public.financial_groups WHERE id=_request_id; IF existing IS NOT NULL THEN RETURN existing; END IF;
IF _source NOT IN ('manual','contract') OR _total<=0 OR nullif(trim(_description),'') IS NULL THEN RAISE EXCEPTION 'Informe origem, descrição e valor.'; END IF;
IF _direction='entrada' AND _work_id IS NULL THEN RAISE EXCEPTION 'Selecione a obra do recebimento.'; END IF;
IF _source='contract' THEN IF _work_id IS NULL OR _direction<>'entrada' THEN RAISE EXCEPTION 'Contrato exige entrada por obra.'; END IF; PERFORM id FROM public.works WHERE id=_work_id FOR UPDATE; SELECT id INTO existing FROM public.financial_groups WHERE work_id=_work_id AND source='contract'; IF existing IS NOT NULL THEN RETURN existing; END IF; IF EXISTS(SELECT 1 FROM public.financial_entries WHERE work_id=_work_id AND direction='entrada' AND NOT canceled) THEN RAISE EXCEPTION 'Já existem recebíveis. Confira os lançamentos antes de gerar o contrato.'; END IF; END IF;
IF jsonb_typeof(_rows)<>'array' THEN RAISE EXCEPTION 'Parcelas inválidas.'; END IF; n:=jsonb_array_length(_rows); IF n<1 OR n>120 THEN RAISE EXCEPTION 'Informe entre 1 e 120 parcelas.'; END IF; SELECT sum((value->>'amount')::numeric) INTO total_rows FROM jsonb_array_elements(_rows); IF total_rows IS DISTINCT FROM _total THEN RAISE EXCEPTION 'Parcelas não fecham o valor total.'; END IF;
INSERT INTO public.financial_groups(id,work_id,source,total) VALUES(_request_id,_work_id,_source,_total);
FOR row IN SELECT * FROM jsonb_array_elements(_rows) LOOP idx:=idx+1; IF (row->>'amount')::numeric<=0 OR nullif(row->>'due_date','') IS NULL THEN RAISE EXCEPTION 'Informe valor positivo e vencimento de cada parcela.'; END IF; INSERT INTO public.financial_entries(work_id,group_id,description,direction,category,person_id,amount,due_date,incurred,installment_index,installment_count,payment_method,notes,cost_center,file_path) VALUES(_work_id,_request_id,_description,_direction,_category,_person_id,(row->>'amount')::numeric,(row->>'due_date')::date,_incurred,idx,n,_payment_method,_notes,_cost_center,_file_path); END LOOP; RETURN _request_id; END $$;
REVOKE ALL ON FUNCTION public.create_financial_installments(uuid,uuid,text,text,text,text,uuid,numeric,jsonb,boolean,text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_financial_installments(uuid,uuid,text,text,text,text,uuid,numeric,jsonb,boolean,text,text,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_installment_purchase(_request_id uuid,_work_id uuid,_supplier_id uuid,_description text,_expected_date date,_lines jsonb,_rows jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE oid uuid; line jsonb; row jsonb; total numeric:=0; total_rows numeric; n integer; idx integer:=0; BEGIN
IF NOT public.can_see_costs(auth.uid()) THEN RAISE EXCEPTION 'Sem permissão.'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(_request_id::text,0)); SELECT payable_order_id INTO oid FROM public.financial_entries WHERE group_id=_request_id LIMIT 1; IF oid IS NOT NULL THEN RETURN oid; END IF;
IF jsonb_typeof(_lines)<>'array' OR jsonb_array_length(_lines)=0 OR jsonb_typeof(_rows)<>'array' THEN RAISE EXCEPTION 'Adicione materiais e parcelas.'; END IF;
INSERT INTO public.purchase_orders(work_id,supplier_id,description,expected_date) VALUES(_work_id,_supplier_id,_description,_expected_date) RETURNING id INTO oid;
FOR line IN SELECT * FROM jsonb_array_elements(_lines) LOOP IF line->>'side'<>'jmg' THEN RAISE EXCEPTION 'Material do cliente não gera compra JMG.'; END IF; INSERT INTO public.purchase_lines(order_id,material_key,name,unit,quantity,unit_price) VALUES(oid,line->>'key',line->>'name',line->>'unit',(line->>'quantity')::numeric,(line->>'price')::numeric); total:=total+(line->>'quantity')::numeric*(line->>'price')::numeric; END LOOP;
total:=round(total,2); n:=jsonb_array_length(_rows); SELECT sum((value->>'amount')::numeric) INTO total_rows FROM jsonb_array_elements(_rows); IF total<=0 OR n<1 OR n>120 OR total_rows IS DISTINCT FROM total THEN RAISE EXCEPTION 'Confira valor total e parcelas da compra.'; END IF;
INSERT INTO public.financial_groups(id,work_id,source,total) VALUES(_request_id,_work_id,'purchase',total);
FOR row IN SELECT * FROM jsonb_array_elements(_rows) LOOP idx:=idx+1; IF (row->>'amount')::numeric<=0 OR nullif(row->>'due_date','') IS NULL THEN RAISE EXCEPTION 'Informe valor e vencimento de cada parcela.'; END IF; INSERT INTO public.financial_entries(work_id,group_id,category,description,person_id,direction,amount,due_date,payable_order_id,installment_index,installment_count) VALUES(_work_id,_request_id,'Materiais',_description,_supplier_id,'saida',(row->>'amount')::numeric,(row->>'due_date')::date,oid,idx,n); END LOOP; RETURN oid; END $$;
REVOKE ALL ON FUNCTION public.create_installment_purchase(uuid,uuid,uuid,text,date,jsonb,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.create_installment_purchase(uuid,uuid,uuid,text,date,jsonb,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.guard_purchase_line() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (to_jsonb(new)-'received') IS DISTINCT FROM (to_jsonb(old)-'received') THEN RAISE EXCEPTION 'Pedido preservado. Registre outro pedido.'; END IF; IF TG_OP='UPDATE' AND new.received<old.received THEN RAISE EXCEPTION 'Recebimento não pode ser reduzido.'; END IF; IF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM public.financial_entries WHERE purchase_order_id=new.order_id OR payable_order_id=new.order_id) THEN RAISE EXCEPTION 'Pedido já finalizado.'; END IF; RETURN new; END $$;